def choose_move(observation):
    x, y = observation['self_position']
    grid_w, grid_h = observation['grid_width'], observation['grid_height']
    opponents = observation['opponent_position']
    resources = observation['resources']
    obstacles = observation['obstacles']
    remaining = observation['remaining_resource_count']

    def dist(ax, ay, bx, by):
        return abs(ax - bx) + abs(ay - by)

    def move_towards(tx, ty):
        dx = dy = 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
        return dx, dy

    def move_away(tx, ty):
        dx = dy = 0
        if tx >= x:
            dx = -1
        elif tx <= x:
            dx = 1
        if ty >= y:
            dy = -1
        elif ty <= y:
            dy = 1
        return dx, dy

    def is_valid(nx, ny):
        if 0 <= nx < grid_w and 0 <= ny < grid_h:
            if (nx, ny) not in obstacles:
                return True
        return False

    # Prioritize resources if any
    if resources:
        # Find closest resource
        r = min(resources, key=lambda res: dist(x, y, res[0], res[1]))
        dx, dy = move_towards(r[0], r[1])
        if is_valid(x + dx, y + dy):
            return [dx, dy]

    # No resources, if opponents exist, evade the closest
    if opponents:
        o = min(opponents, key=lambda opp: dist(x, y, opp[0], opp[1]))
        dx, dy = move_away(o[0], o[1])
        if is_valid(x + dx, y + dy):
            return [dx, dy]

    # Else, move randomly towards unblocked direction
    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
        nx, ny = x + dx, y + dy
        if is_valid(nx, ny):
            return [dx, dy]
    return [0, 0]
